package com.warproject.launcher;
import java.lang.reflect.*;import java.nio.file.*;
public class LibraryIntegration {public static void main(String[] a)throws Exception{
 Path root=Files.createTempDirectory("pb-library");Class<?> c=Class.forName("com.warproject.launcher.ProjectBattleAlpha$Config");var ctor=c.getDeclaredConstructor(Path.class);ctor.setAccessible(true);Object config=ctor.newInstance(root);Class<?> sink=Class.forName("com.warproject.launcher.ProjectBattleAlpha$LogSink");Object log=Proxy.newProxyInstance(sink.getClassLoader(),new Class[]{sink},(o,m,args)->null);Class<?> r=Class.forName("com.warproject.launcher.ProjectBattleAlpha$Runner");var rc=r.getDeclaredConstructor(c,sink);rc.setAccessible(true);Object runner=rc.newInstance(config,log);Method repair=r.getDeclaredMethod("ensureLibraryFile",Path.class,String.class,String.class);repair.setAccessible(true);Path jar=root.resolve("gson.jar");Files.writeString(jar,"truncated jar");repair.invoke(runner,jar,"https://libraries.minecraft.net/com/google/code/gson/gson/2.10/gson-2.10.jar","library");if(!PackMaintenance.readableJar(jar))throw new AssertionError();String hash=PackMaintenance.sha256(jar);repair.invoke(runner,jar,"https://invalid.invalid/not-used","library");if(!hash.equals(PackMaintenance.sha256(jar)))throw new AssertionError();System.out.println("PASS damaged library restored; valid library retained");}}
